UPDATE marketplace_styles 
SET style_config = jsonb_set(
  jsonb_set(
    style_config::jsonb,
    '{imageGeneration,prompt_style}',
    '"=== ELLOCONTENT EXCLUSIVE STYLE ===\nCreate an Instagram carousel post in the ELLOCONTENT EXCLUSIVE visual style. This style is defined by REALISTIC DEVICE MOCKUPS showcasing app/website screenshots on dark cinematic backgrounds with bold typography.\n\n=== BACKGROUND ===\nDark gradient background ranging from deep black (#0D0D0D) to deep purple/violet (#2D1B69, #4C1D95). The gradient should be smooth and cinematic, sometimes with subtle purple light flares or glow effects. Never use flat solid colors. The mood is premium, tech-forward, and sophisticated.\n\n=== CORE VISUAL ELEMENT: DEVICE MOCKUPS ===\nEVERY card MUST feature a realistic 3D device mockup as the central visual element:\n- For MOBILE content: Use a photorealistic iPhone mockup (latest model) showing a dark-themed app interface on screen. The phone should be held by a hand, floating at an angle, or placed on a surface. NEVER flat/frontal.\n- For DESKTOP content: Use a photorealistic MacBook/iMac mockup showing a dark-themed web interface. Place it on a stone surface, desk, or floating. Add environmental context.\n- The screen content should show a dark UI with purple accents (similar to a content creation app interface).\n- Lighting: Dramatic studio lighting with purple/violet rim lights and reflections on the device.\n- VARY the device angle, position, and context across cards. Examples: hand holding phone from side, phone hanging from purple cord, laptop on stone pedestal, phone with gloved hand, monitor at angle.\n\n=== TYPOGRAPHY ===\nBold, heavy sans-serif font (like Montserrat Black or similar).\n- Titles: VERY LARGE, bold, white (#FFFFFF) with specific words highlighted using a purple (#8B5CF6) background box/pill.\n- The highlighted word technique is SIGNATURE. At least one key word per card should have a purple highlight behind it.\n- Secondary text: Medium weight, white or light gray, significantly smaller than titles.\n- Text placement: Usually top portion of the card, above or beside the device mockup.\n- Some cards may have text boxes with rounded corners and subtle borders at the bottom.\n\n=== LAYOUT ===\nAsymmetric editorial layouts:\n- Title text occupies top 25-35% of the card.\n- Device mockup occupies center-bottom 60-70%.\n- Text and device may overlap slightly for depth.\n- Generous negative space around elements.\n- Left or center alignment for text.\n\n=== COLORS (MANDATORY) ===\n#0D0D0D (deep black background), #1A1033 (dark purple), #4C1D95 (medium purple), #8B5CF6 (accent purple for highlights), #FFFFFF (titles and primary text), #A0A0A0 (secondary/body text)\n\n=== DECORATIVE ===\nSubtle purple light flares, reflections on devices, environmental shadows. NO geometric shapes, NO grid patterns, NO borders/frames. Clean and minimal. The device mockup IS the decoration.\n\n=== PHOTO TREATMENT ===\nHyper-realistic 3D rendering style for devices. Cinematic lighting with purple/violet color cast. High contrast. Professional product photography aesthetic.\n\n=== VARIATION RULES ===\n- Card 1 (COVER): Bold title + iPhone or MacBook mockup. Most impactful composition.\n- Cards 2-4 (CONTENT): Alternate between iPhone and MacBook mockups. Vary angles and hand positions. Each card shows a different screen/feature.\n- Last card (CTA): Can use a more minimal layout with just typography, or a device at a dramatic angle.\n- NEVER repeat the same device angle or position across consecutive cards.\n\nRULES: Full bleed. Portugues brasileiro. NAO copie @handles/nomes das referencias. O resultado DEVE parecer um post premium de lancamento de produto tech."'::jsonb
  ),
  '{imageGeneration,negative_prompt}',
  '"cartoon, anime, illustration, stock photo, generic corporate, flat design, minimalist, grid layout, mosaic, white borders, frames, margins, wireframe, low quality render, blurry device screen"'::jsonb
)
WHERE id = '391b30f6-204f-49b2-a2ab-a2b114141e96';